pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a simple ERC721 token to use for testing
        // We'll use a minimal inline token
        ERC721Mock nft = new ERC721Mock("Test", "TST");

        // Mint an NFT to this test contract
        nft.mint(address(this), 1);

        // Approve the C contract to transfer the NFT
        nft.approve(address(c), 1);

        // Set up the C contract with the NFT address and no base token
        // We need to initialize the pool first
        // Since C uses onlyOwner modifier, we need to be the owner
        // The factory is set to address(this) in setUp, so ownerOf(uint160(address(c))) should work
        // But actually the factory is address(this), which is the test contract, not the C contract
        // Let's reconsider: the owner check is msg.sender != Factory(factory).ownerOf(uint160(address(this)))
        // We set factory = address(this) in setUp, so we need to be the owner of the pool NFT
        // The pool NFT is minted in Factory.create, but we don't use Factory here
        // We'll just interact with the public deposit function which doesn't have onlyOwner

        uint256[] memory tokenIds = new uint256[](1);
        tokenIds[0] = 1;

        // Try to deposit the NFT into the pool
        // In the reference: onERC721Received returns selector, safeTransferFrom succeeds, deposit succeeds
        // In the buggy version: onERC721Received returns 0 bytes, safeTransferFrom reverts, deposit reverts

        // We'll catch the revert
        bool depositSucceeded;
        vm.prank(address(this));
        try c.deposit(tokenIds, 0) {
            depositSucceeded = true;
        } catch {
            depositSucceeded = false;
        }

        // The reference: deposit succeeds (true), the buggy: deposit reverts (false)
        assertTrue(depositSucceeded);
    }
}

// Minimal ERC721 token for testing
contract ERC721Mock {
    string public name;
    string public symbol;

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;

    constructor(string memory _name, string memory _symbol) {
        name = _name;
        symbol = _symbol;
    }

    function mint(address to, uint256 tokenId) external {
        _owners[tokenId] = to;
        _balances[to]++;
    }

    function ownerOf(uint256 tokenId) external view returns (address) {
        return _owners[tokenId];
    }

    function approve(address to, uint256 tokenId) external {
        _tokenApprovals[tokenId] = to;
    }

    function getApproved(uint256 tokenId) external view returns (address) {
        return _tokenApprovals[tokenId];
    }

    function transferFrom(address from, address to, uint256 tokenId) external {
        require(_owners[tokenId] == from, "wrong from");
        _owners[tokenId] = to;
        _balances[from]--;
        _balances[to]++;
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        transferFrom(from, to, tokenId);
        if (to.code.length > 0) {
            (bool success, bytes memory data) = to.staticcall(
                abi.encodeWithSelector(
                    bytes4(keccak256("onERC721Received(address,address,uint256,bytes)")),
                    address(this),
                    from,
                    tokenId,
                    ""
                )
            );
            require(success && data.length == 32 && abi.decode(data, (bytes4)) == bytes4(keccak256("onERC721Received(address,address,uint256,bytes)")), "unsafe");
        }
    }

    function balanceOf(address owner) external view returns (uint256) {
        return _balances[owner];
    }
}

