        c.initialize(address(0), nft, 1000 ether, 100 ether, 0.01 ether, 100, bytes32(0), false, false);

        // Mint an NFT to the pool to make it available for flash loan
        // Since we can't mint easily, we simulate by directly setting owner via raw call (not possible)
        // Instead, we'll just test that the flashLoan function reverts as expected due to baseToken mismatch

        // The bug: baseToken stays address(0) but flashFeeToken() returns address(0) and the caller must send ETH fee
        // Flash loan an NFT that doesn't exist – will revert because not available
        bool ok;
        try c.flashLoan(IERC3156FlashBorrower(address(this)), nft, 1, "") {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference, baseToken = address(0) so ETH flow works; in bug, baseToken = address(0) too, so no difference here.
        // Actually, the difference is in baseToken getter: reference returns address(0) correctly, bug returns address(0) too.
        // Let's find the real divergence: the assign statement removed means baseToken stays default (address(0)).
        // Both return address(0) – so no difference on the getter.
        // The divergence is that in reference baseToken is set, in bug it's not, but both read as zero.
        // We need a case where the contract checks baseToken != address(0) vs baseToken == address(0) inside.
        // Use a non-zero baseToken: e.g., WETH, then the bug leaves baseToken=0 causing wrong branch.

        // Let's redo with a non-ETH baseToken
        c = new C(address(this), address(this), address(this));
        address weth = address(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2);
        c.initialize(weth, nft, 1000 ether, 100 ether, 0.01 ether, 100, bytes32(0), false, false);

        // In reference, baseToken == weth; in bug, baseToken == address(0)
        // So flashFeeToken() returns weth in reference, address(0) in bug
        // This affects flashLoan: reference expects ERC20 transfer, bug expects ETH
        // Try flash loan – will fail because NFT not owned, but the fee handling path differs
        try c.flashLoan(IERC3156FlashBorrower(address(this)), nft, 1, "") {
            ok = true;
        } catch {
            ok = false;
        }
        // Both revert due to not available, so no observable difference.
